'use strict';(()=>{
const catalogue=[["Planners & trackers","A week you can actually plan.","Turn a list of competing tasks into a plan people can follow.","Set priorities|Assign tasks|Review progress"],["Healthcare systems","One record, a clearer picture.","In development: a medical reporting concept for hospitals, pharmacies and health centres. Explore how daily records could inform aggregate reporting on illnesses, medicines and suspected reactions.","Record activity|Review medicine use|Report trends"],["Project management","Who owns the next step?","Explore milestones, responsibilities and approval queues for a team juggling several projects.","Assign an owner|Track milestones|Resolve delays"],["Document management","Which version is approved?","Explore controlled documents with version history, review dates and access by role.","Draft a document|Request review|Find the approved copy"],["Supply & demand","What needs replenishing?","Explore a purchasing view that puts demand, available stock and incoming orders together.","Review demand|Check stock|Plan an order"],["Point of sale","From basket to receipt.","A retail pharmacy prototype connects checkout to stock, including brand selection, expiry dates and blocked stock.","Build a basket|Check availability|Issue a receipt"],["Web development","Give the idea an address.","Build a website or browser app around the job your visitors came to do. VybaCash is one example already in use.","Map the journey|Try a preview|Refine the experience"],["Property management","What needs attention today?","Explore a workspace for units, rent records and maintenance requests across properties.","Review units|Check rent records|Assign repairs"]],id=x=>document.getElementById(x),controls=[...document.querySelectorAll('[data-pick]')];let current=0;
function select(n){current=n;const [label,title,desc,steps]=catalogue[n];controls.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)));id('desk-title').textContent=title;id('desk-copy').textContent=desc;id('sheetnum').textContent=String(n+1).padStart(2,'0')+' / 08';id('desk-steps').replaceChildren(...steps.split('|').map(step=>{const li=document.createElement('li');li.textContent=step;return li}));}
controls.forEach((b,i)=>b.onclick=()=>select(i));
id('start-brief').onclick=()=>{id('kind').value=catalogue[current][0];id('idea').focus({preventScroll:true})};
id('work-search').onclick=()=>id('search').focus({preventScroll:true});
function body(){return 'Project direction: '+(id('kind').value||'Open idea')+'\n\n'+id('idea').value.trim()+'\n\nFrom: '+id('who').value.trim()}
id('brief-form').onsubmit=e=>{e.preventDefault();location.href='mailto:hello@greylad.me?subject='+encodeURIComponent('Greylad idea: '+(id('kind').value||'New project'))+'&body='+encodeURIComponent(body());id('brief-result').textContent='If no email app opened, use Copy brief.'};
id('copybrief').onclick=async()=>{if(!id('brief-form').reportValidity())return;try{await navigator.clipboard.writeText(body());id('brief-result').textContent='Brief copied.'}catch{id('brief-result').textContent=body()}};
})();
